    for i in range(1, n + 1):
        parts = lines[i].split()
        t, x_prime, y = int(parts[0]), int(parts[1]), int(parts[2])
        x = x_prime / 100000.0
        ops.append((t, x, y))

    # Find reachable values at each step using DP
    # reachable[i] = set of banana counts reachable after step i
    reachable = [set() for _ in range(n + 1)]
    reachable[0] = {0}

    # Track earliest time for each target
    answer = [-1] * m

    for step in range(1, n + 1):
        t, x, y = ops[step - 1]
        prev = reachable[step - 1]
        reachable[step] = set(prev)  # Can choose a_i = 0

        # From each value in previous step, apply operation a_i times
        for val in prev:
            if val >= m:
                continue

            # Type 1: k := ceil(k + x), repeated a times
            if t == 1:
                current = val
                for a in range(1, y + 1):
                    current = int(current + x)
                    if 1 <= current <= m:
                        if answer[current - 1] == -1:
                            answer[current - 1] = step
                        if current >= m:
                            break
                        new_val = current
                        if new_val not in reachable[step]:
                            reachable[step].add(new_val)

            # Type 2: k := ceil(k * x), repeated a times
            elif t == 2:
                current = val
                for a in range(1, y + 1):
                    current = int(current * x)
                    if 1 <= current <= m:
