# Binary Indexed Tree (Fenwick Tree) implementation
class FenwickTree:
    def __init__(self, size):
        self.size = size
        self.tree = [0] * (size + 1)

    def update(self, i, delta):
        """Add delta to element at index i (1-indexed)"""
        i += 1  # 0-indexed to 1-indexed conversion
        while i <= self.size:
            self.tree[i] += delta
            i += i & (-i)

    def query(self, i):
        """Query sum from 0 to i (inclusive, 0-indexed)"""
        i += 1  # 0-indexed to 1-indexed conversion
        s = 0
        while i > 0:
            s += self.tree[i]
            i -= i & (-i)
        return s

    def query_range(self, l, r):
        """Query sum from l to r (inclusive, 0-indexed)"""
        if l > r:
            return 0
        return self.query(r) - (self.query(l - 1) if l > 0 else 0)


