def solution(input_str):
    lines = input_str.strip().split('\n')
    parts = lines[0].split()
    x, k, n, q = int(parts[0]), int(parts[1]), int(parts[2]), int(parts[3])

    c = list(map(int, lines[1].split()))

    special_stones = {}
    for i in range(2, 2 + q):
        p, wp = map(int, lines[i].split())
        special_stones[int(p)] = int(wp)

    # Edge case: already at target
    if n == x:
        return "0\n"

    # DP state: (pos, rels)
    # pos = position of leftmost pollywog
    # rels = tuple of offsets: rels[i] is distance from index i+1 pollywog to leftmost
    from functools import lru_cache

    @lru_cache(maxsize=None)
    def dp(pos, rels):
        if pos == n - x + 1:
            return 0

        min_cost = float('inf')

        for dist in range(1, min(k + 1, n - x + 1)):
            if pos + dist < n - x + 1:
                # Jump the leftmost pollywog
                jump_cost = c[dist - 1]
                special_cost = special_stones.get(pos + dist - 1, 0)
                cost = jump_cost + special_cost

                # Calculate new relative positions
                new_rels = tuple(r + dist for r in rels)

                # Calculate base position of rightmost pollywog
                # When leftmost reaches target, rightmost must also reach target
                # We need to find if there's a valid continuation
                base_from_rels = pos + new_rels[-1] if new_rels else pos

                if min_cost != float('inf'):
                    next_cost = dp(pos + dist, new_rels)
                    if next_cost != float('inf'):
                        min_cost = min(min_cost, cost + next_cost)

        return min_cost

    # Handle x=1 case directly
    if x == 1:
        dist = n - 1
        if dist <= k:
            return f"{c[dist-1] + special_stones.get(n, 0)}\n"
        else:
            return "-1\n"

    if n < x + 1 - k:
        return "-1\n"

    # Initial state: leftmost at 1, rightmost at x
    initial_rels = tuple(i + 1 for i in range(x - 1))

    result = dp(1, initial_rels)

    if result == float('inf'):
        return "inf\n"

    return f"{result}\n"

