    asterisks = []

    for i, c in enumerate(field):
        if c == 'P':
            packmen.append(i)
        elif c == '*':
            asterisks.append(i)

    if not packmen or not asterisks:
        return "0 0"

    best_count = 0
    best_time = float('inf')
    num_packmen = len(packmen)

    # Enumerate all 2^num_packmen direction combinations
    for direction_combo in range(1 << num_packmen):
        eaten = set()
        max_time = 0

        for i in range(num_packmen):
            px = packmen[i]
            is_right = (direction_combo >> i) & 1

            if is_right:
                # Packman moves right - eat asterisks to the right
                for ast in asterisks:
                    if ast > px and ast not in eaten:
                        eaten.add(ast)
                        max_time = max(max_time, ast - px)
            else:
                # Packman moves left - eat asterisks to the left
                for ast in asterisks:
                    if ast < px and ast not in eaten:
                        eaten.add(ast)
                        max_time = max(max_time, px - ast)

        count = len(eaten)
        # Maximize count first, then minimize time
        if count > best_count:
            best_count = count
            best_time = max_time
        elif count == best_count and max_time < best_time:
            best_time = max_time

    return f"{best_count} {int(best_time)}"

