    lines = input_str.strip().split('\n')
    if not lines:
        return '0'

    first = lines[0].split()
    N, M, K = int(first[0]), int(first[1]), int(first[2])

    if K == 0 or N == 0 or M == 0:
        return '0'

    costs = {}

    for i in range(K):
        parts = lines[i + 1].split()
        x, y, d, t, e = int(parts[0]), int(parts[1]), int(parts[2]), int(parts[3]), int(parts[4])

        positions = [(x, y), (x + d, y - d), (x + d, y), (x, y + d)]

        for offset, (px, py) in enumerate(positions):
            visit_time = px + py
            if 0 <= px < N and 0 <= py < M and visit_time >= t and (visit_time - t) % 4 == offset:
                costs[(px, py, visit_time)] = costs.get((px, py, visit_time), 0) + e

    dp = [[float('inf')] * M for _ in range(N)]
    dp[0][0] = costs.get((0, 0, 0), 0)

    for r in range(N):
        for c in range(M):
            if r == 0 and c == 0:
                continue
            prev = float('inf')
            if r > 0:
                prev = min(prev, dp[r-1][c])
            if c > 0:
                prev = min(prev, dp[r][c-1])

            if prev != float('inf'):
                dp[r][c] = prev + costs.get((r, c, r+c), 0)

    result = dp[N-1][M-1]

    if result == float('inf'):
        return '0'

    return str(result)

