                # Choice match - match s1[i-1] and s2[j-1]
                if i > 0 and j > 0 and s1[i-1] == s2[j-1]:
                    nk = kmp_next_state(k, s1[i-1])
                    if nk < v:
                        if dp[i][j][nk] == inf or val + 1 < dp[i][j][nk]:
                            dp[i][j][nk] = val + 1
                            par[i][j][nk] = (i, j, k, 'match')

    # Find best result from all valid ending states
    best_len = 0
    best_k = 0
    for k in range(v):
        if dp[n][m][k] > best_len:
            best_len = dp[n][m][k]
            best_k = k
        elif dp[n][m][k] == best_len and best_len > 0 and k < best_k:
            best_k = k

    if best_len == 0:
        return "0"

    # Reconstruct the LCS
    i, j, k = n, m, best_k
    result = []

    while (i, j, k) != (0, 0, 0) and dp[i][j][k] != inf:
        p = par[i][j][k]
        if p is None:
            break

        pi_prev, pj_prev, pk_prev, op = p

        if op == 'match':
            result.append(s1[i-1])
        # For skip transitions, the character was not added

        i, j, k = pi_prev, pj_prev, pk_prev

    return ''.join(reversed(result))

