def solve_custom(n, m, edges, queries):
    # Tarjan's SCC algorithm
    index_counter = [0]
    stack = []
    lowlink = [0] * (n + 1)
    on_stack = [False] * (n + 1)
    indices = [-1] * (n + 1)
    scc_id = [-1] * (n + 1)
    scc_list = []

    def strongconnect(v):
        indices[v] = index_counter[0]
        lowlink[v] = index_counter[0]
        index_counter[0] += 1
        stack.append(v)
        on_stack[v] = True

        for w, w_len in edges[v]:
            if indices[w] == -1:
                strongconnect(w)
                lowlink[v] = min(lowlink[v], lowlink[w])
            elif on_stack[w]:
                lowlink[v] = min(lowlink[v], indices[w])

        if lowlink[v] == indices[v]:
            component = []
            while True:
                w = stack.pop()
                on_stack[w] = False
                component.append(w)
                scc_id[w] = len(scc_list)
                if w == v:
                    break
            scc_list.append(component)

    for i in range(1, n + 1):
        if indices[i] == -1:
            strongconnect(i)

    # For each SCC with size >= 2, compute GCD of all cycle lengths
    # 因为这是一个有向图，我们需要仔细处理

    scc_gcd = [0] * len(scc_list)
    visited_nodes = [False] * (n + 1)
    seen = [False] * (n + 1)

    def get_cycle_gcd_in_scc(scc):
        start = scc[0]
        cycles_mod = {}
        visited = {start: 0}
        stack = [(start, 0)]
        gcd_val = 1

        while stack:
            node, dist = stack.pop()
            if node in seen:
                gc = gcd(gcd_val, abs(visited[node] - visited[node]))
                continue
            seen[node] = True

            for w, w_len in edges[node]:
                if w in scc:
                    if w in visited:
                        cycle_len = visited[node] + w_len - visited[w]
                        gcd_val = gcd(gcd_val, abs(cycle_len))
                    else:
                        if w not in visited:
                            visited[w] = visited[node] + w_len
                            stack.append((w, visited[w]))

        while visited:
            key, val = visited.popitem()
            if key not in seen:
                seen[key] = True

        return gcd_val if gcd_val > 0 and seen[start] else 0

    for scc in scc_list:
        if len(scc) >= 2:
            scc_gcd[-1] = get_cycle_gcd_in_scc(scc)

    results = []
