    q = int(lines[0])
    queries = []

    # Find max n for sieve and factorial array sizing
    max_n = 0
    for i in range(1, len(lines)):
        if lines[i].strip():
            r, n = map(int, lines[i].split())
            queries.append((r, n))
            max_n = max(max_n, n)

    MOD = 10**9 + 7
    MAX_N = max(2, max_n + 1)

    # Precompute factorials and inverse factorials
    fact = [1] * MAX_N
    inv = [1] * MAX_N

    for i in range(1, MAX_N):
        fact[i] = (fact[i-1] * i) % MOD

    inv[MAX_N-1] = pow(fact[MAX_N-1], MOD-2, MOD)
    for i in range(MAX_N-2, -1, -1):
        inv[i] = (inv[i+1] * (i+1)) % MOD

    def nCr(n, r):
        if r < 0 or r > n:
            return 0
        return fact[n] * inv[r] % MOD * inv[n-r] % MOD

    # Sieve for prime factorization (smallest prime factor for each number)
    min_prime = [0] * MAX_N
    for i in range(2, MAX_N):
        if min_prime[i] == 0:
            for j in range(i, MAX_N, i):
                min_prime[j] = i

    results = []
    for r, n in queries:
        if r == 0:
            # f0(n) = 2^ω(n) where ω(n) is number of distinct prime factors
            temp = n
            distinct = 0
            while temp > 1:
                p = min_prime[temp]
                while temp % p == 0:
                    temp //= p
                distinct += 1
            results.append(pow(2, distinct, MOD))
        else:
            # fr(n) = product of fr(p^k) for each prime factor
            # fr(p^k) = C(k+r, k) + C(k+r-1, k-1)
            temp = n
            res = 1
            while temp > 1:
                p = min_prime[temp]
                count = 0
                while temp % p == 0:
                    count += 1
                    temp //= p
                term = (nCr(count + r, count) + nCr(count + r - 1, count - 1)) % MOD
                res = (res * term) % MOD
            results.append(res)

    return '\n'.join(map(str, results))

