def solve(n, m, k):
    """Solve the problem of counting great arrays."""
    # For n=1, no valid good arrays exist (single element can't have diff=1 with self in circle)
    if n == 1:
        return 0

    MOD = 1000000007
    count = 0

    # Generate all non-decreasing arrays of length n with elements in [1, m]
    # Non-decreasing arrays correspond to multisets of size n from [1, m]
    # Count using combinatorics: C(n+m-1, n)
    # But need to filter by good array constraints

    # Generate non-decreasing arrays
    from itertools import combinations_with_replacement

    for combo in combinations_with_replacement(range(1, m+1), n):
        arr = list(combo)

        # Check if this array can form good arrays when rearranged
        # For length >= 2, count permutations that are good

        # Good array requirement: |a[i] - a[(i+1)%n]| = 1 for all i

        # Check if ANY rearrangement forms a good array
        can_form_good = False
        good_count = 0

        from itertools import permutations
        for perm in set(permutations(arr)):
            is_good = True
            for i in range(n):
                if abs(perm[i] - perm[(i+1)%n]) != 1:
                    is_good = False
                    break
            if is_good:
                can_form_good = True
                good_count += 1

        # Great array requirement: 1 <= good_count <= k
        if 1 <= good_count <= k:
            count = (count + 1) % MOD

    return count

